@js:
Time = 1296e3;//(15天)
聆听音乐 = cache.getFile('聆听音乐');
if(聆听音乐==null){
java.toast('正在获取歌曲标签')

function getTitle(title,style){
		if(style==0){
				title = '༺ˇ»`ʚ'+title+'ɞ´«ˇ༻'
			}
		else{
				title = '༺ '+title+' ༻'
			}
		return '{"title":"'+title+'","url":"","style":{"layout_flexBasisPercent":1}},'
	}

function getSort(title,uid){
		url = String(uid).match(/baidu/) ? uid : 'http://101.43.12.135:3200/getSongLists?categoryId=' + uid + '&page={{page}\}'
		return '{"title":"'+title+'","url":"'+url+'","style":{"layout_flexGrow":1}},'
	}


聆听音乐 = getTitle('聆听音乐',0)+getSort('自定义歌单','https://www.baidu.com/')
JSON.parse(java.ajax('http://101.43.12.135:3200/getSongListCategories')).response.data.categories.map($=>{
		聆听音乐 += getTitle($.categoryGroupName,1)
		$.items.map($=>{
				聆听音乐 += getSort($.categoryName.replace('#38;',''),$.categoryId)
			});
	});
cache.putFile('聆听音乐', 聆听音乐, Time);
java.toast('获取成功，默认保存15天')
}

